import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd();

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run(['cargo', 'run', '-q', '-p', 'fz', '--', 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return payload

def messages(payload):
    return [item['message'] for item in payload['items']]

def helps(payload):
    return [item.get('help') for item in payload['items']]

relay_mismatch = verify('relay_mismatch', '''
    fn borrow(v: &'b i32) -> &'b i32 {
        return v
    }
    fn relay(a: &'a i32, b: &'b i32) -> &'a i32 {
        return borrow(b)
    }
    fn main() -> i32 {
        return 0
    }
''', 1)
assert any('returns reference expression with mismatched lifetime' in message for message in messages(relay_mismatch)), relay_mismatch
assert any(help == 'return the reference tied to the declared output lifetime on every path, or return an owned value instead' for help in helps(relay_mismatch)), relay_mismatch
assert not any('call signature mismatch for `borrow`' in message for message in messages(relay_mismatch)), relay_mismatch

assignment_drift = verify('assignment_drift', '''
    fn borrow_a(v: &'a i32) -> &'a i32 {
        return v
    }
    fn borrow_b(v: &'b i32) -> &'b i32 {
        return v
    }
    fn relay(a: &'a i32, b: &'b i32) -> &'a i32 {
        let mut out = borrow_a(a)
        if true {
            out = borrow_b(b)
        }
        return out
    }
    fn main() -> i32 {
        return 0
    }
''', 1)
assert any(('returns reference expression with mismatched lifetime' in message) or ('returns reference expression without a statically traced lifetime source' in message) for message in messages(assignment_drift)), assignment_drift
assert any((help == 'bind the returned reference to one explicit input lifetime before returning, or switch the API to an owned return') or (help == 'return the reference tied to the declared output lifetime on every path, or return an owned value instead') for help in helps(assignment_drift)), assignment_drift

if_expr_drift = verify('if_expr_drift', '''
    fn relay(flag: i32, a: &'a i32, b: &'b i32) -> &'a i32 {
        return if flag == 0 { a } else { b }
    }
    fn main() -> i32 {
        return 0
    }
''', 1)
assert any(('returns reference expression with mismatched lifetime' in message) or ('returns reference expression without a statically traced lifetime source' in message) for message in messages(if_expr_drift)), if_expr_drift
assert any((help == 'bind the returned reference to one explicit input lifetime before returning, or switch the API to an owned return') or (help == 'return the reference tied to the declared output lifetime on every path, or return an owned value instead') for help in helps(if_expr_drift)), if_expr_drift

same_lifetime_clean = verify('same_lifetime_clean', '''
    fn borrow(v: &'a i32) -> &'a i32 {
        return v
    }
    fn relay(a: &'a i32) -> &'a i32 {
        return borrow(a)
    }
    fn main() -> i32 {
        return 0
    }
''', 0)
assert same_lifetime_clean['errors'] == 0, same_lifetime_clean
assert not any('mismatched lifetime' in message for message in messages(same_lifetime_clean)), same_lifetime_clean
assert not any('without a statically traced lifetime source' in message for message in messages(same_lifetime_clean)), same_lifetime_clean

print('compiler-memory-reference-lifetimes-ok')

